-- 加入五级分类功能
delete from bifrost_function where code='classification';

-- 权限控制 根据角色获取能查询的客户部门信息
delete from bifrost_function where code='userselectorg';


-- 统一视图菜单权限重构
-- 插入部门功能关联
delete from bifrost_org_menu_function where menu_id= (select id from bifrost_menu bm where code = 'customerView');











-- 插入角色功能关联
delete from bifrost_role_menu_function where menu_id= (select id from bifrost_menu bm where code = 'customerView');






















